        .req_id = 123456789,
        .channel_id = 1234,
        .adapter = 42,
        .account = "aaaaaaaaaaaaaaaa",
        .cl_ord_id = "aaaaaaaaaaaaaaaa",
        .orig_cl_ord_id = "aaaaaaaaaaaaaaaa",
        .security_id = "aaaaaaaaaaaa",
        .side = 42,
        .ts_recv_ns = 123456789,
        .raw_ref = 123456789,
